1: // DOCUMENTS: the Stage 5 Worker Queue component — manages an asynchronous
2: // background job queue (`10.40`) and worker executor (`10.41`). Jobs are enqueued
3: // via POST requests, queued FIFO, processed across `jobDurationTicks`, and
4: // written to the database upon completion.
5: //
6: // CHECKS: constructor validates mini-IP addresses (`/^\d+\.\d+$/`) and
7: // `jobDurationTicks` as an integer >= 1.
8: export function createWorkerQueue({
9:   address = '10.40',
10:   workerAddress = '10.41',
11:   jobDurationTicks = 2,
12: } = {}) {
13:   for (const [name, addr] of [
14:     ['address', address],
15:     ['workerAddress', workerAddress],
16:   ]) {
17:     if (!/^\d+\.\d+$/.test(addr)) {
18:       throw new Error(`queue: invalid mini-IP address ${name}=${addr}`);
19:     }
20:   }
21:   if (!Number.isInteger(jobDurationTicks) || jobDurationTicks < 1) {
22:     throw new Error(`queue: jobDurationTicks must be an integer >= 1, got ${jobDurationTicks}`);
23:   }
24: 
25:   let jobs = []; // pending queued jobs
26:   let enqueued = 0;
27:   let completed = 0;
28:   let activeJob = null; // { jobId, path, payload, queuedAtTick, startedAtTick, finishesAtTick }
29:   let nextJobId = 1;
30:   let lastJobResult = null;
31: 
32:   function enqueue(path, payload, currentTick = 0) {
33:     const jobId = nextJobId++;
34:     enqueued += 1;
35:     const job = {
36:       jobId,
37:       path,
38:       payload,
39:       status: 'queued',
40:       queuedAtTick: currentTick,
41:     };
42:     jobs.push(job);
43:     return job;
44:   }
45: 
46:   function step(database, currentTick = 0) {
47:     // If we have an active job finishing at or before currentTick, complete it
48:     if (activeJob && currentTick >= activeJob.finishesAtTick) {
49:       if (database && typeof database.write === 'function') {
50:         database.write(activeJob.path, activeJob.payload, currentTick);
51:       }
52:       lastJobResult = {
53:         jobId: activeJob.jobId,
54:         path: activeJob.path,
55:         payload: activeJob.payload,
56:         completedAtTick: currentTick,
57:       };
58:       completed += 1;
59:       activeJob = null;
60:     }
61: 
62:     // If no active job and there are queued jobs, start the next one
63:     if (!activeJob && jobs.length > 0) {
64:       const job = jobs.shift();
65:       activeJob = {
66:         ...job,
67:         status: 'active',
68:         startedAtTick: currentTick,
69:         finishesAtTick: currentTick + jobDurationTicks,
70:       };
71:     }
72:   }
73: 
74:   function snapshot(currentTick = 0) {
75:     void currentTick;
76:     return {
77:       address,
78:       workerAddress,
79:       jobDurationTicks,
80:       enqueued,
81:       completed,
82:       activeJob: activeJob ? { ...activeJob } : null,
83:       pendingJobs: jobs.map((j) => ({ ...j })),
84:       lastJobResult: lastJobResult ? { ...lastJobResult } : null,
85:     };
86:   }
87: 
88:   return {
89:     get address() {
90:       return address;
91:     },
92:     get workerAddress() {
93:       return workerAddress;
94:     },
95:     enqueue,
96:     step,
97:     snapshot,
98:   };
