// DOCUMENTS: the network — the wiring that lets two-number mini-IP
// addressable components exchange messages. Today it carries slim HTTP
// requests to a registered server; later stages attach more components
// without changing the send/enqueue contract. Stage 6 adds cross-subnet
// routing: a fabric owns one subnet, and a destination on another subnet
// takes exactly one hop through the attached Router into the far fabric's
// own delivery contract.
//
// CHECKS: every address crossing the wire is validated as a two-number
// mini-IP (<net>.<host>), and sends to unregistered hosts fail loud —
// same-subnet (11.1 without a router) and far-subnet (20.9 behind the
// Router) alike.
const MINI_IP = /^\d+\.\d+$/;

export function createNetwork(subnet = '10') {
  const servers = new Map();
  let router = null;

  function validate(addr) {
    if (!MINI_IP.test(addr)) {
      throw new Error(`network: invalid mini-IP address ${addr}`);
    }
  }

  function resolve(address) {
    validate(address);
    const server = servers.get(address);
    if (!server) {
      throw new Error(`network: no server at ${address}`);
    }
    return server;
  }

  // CHECKS: a destination on a foreign subnet routes through the attached
  // Router (one hop, the Router counts it); with no Router attached the
  // delivery falls through to the local registry and fails loud there —
  // the stage 1-5 send contract is unchanged.
  function crossSubnet(to, forward) {
    if (String(to).split('.')[0] === subnet) return null;
    if (!router) return null;
    return forward(router);
  }

  return {
    registerServer(address, server) {
      validate(address);
      servers.set(address, server);
    },

    resolve,

    attachRouter(attached) {
      router = attached;
    },

    send({ from, to, request }) {
      validate(from);
      validate(to);
      const routed = crossSubnet(to, (r) => r.forward({ from, to, request }));
      if (routed) return routed;
      const server = resolve(to);
      const response = server.handleRequest(request);
      return { from, to, request, response };
    },

    deliverToQueue({ id, from, to, request, atTick, isYou = false }) {
      validate(from);
      validate(to);
      const routed = crossSubnet(to, (r) => r.forwardToQueue({ id, from, to, request, atTick, isYou }));
      if (routed) return routed;
      const server = resolve(to);
      server.enqueue({ id, from, to, request, atTick, isYou });
    },
  };
}
