// DOCUMENTS: the Stage 6 component — a DNS resolver with a tick-TTL ledger.
// An authoritative table (example.com -> 10.1; Stage 6b adds the CDN name)
// answers only a cache miss or an expired entry; a hit inside ttlTicks is
// served from the ledger without touching the authority — a real Map lookup
// on the ask path, not a hit probability. Deterministic by construction: no
// clock, no RNG — time arrives as the currentTick argument, the same way the
// Cache keeps time.
//
// CHECKS: the constructor rejects an address that is not a two-number
// mini-IP and a ttlTicks that is not a positive integer (fail-loud over
// silent mis-configuration).
const AUTHORITATIVE = new Map([['example.com', '10.1']]);

export function createDns({ address = '10.60', ttlTicks = 300 } = {}) {
  if (!/^\d+\.\d+$/.test(address)) {
    throw new Error(`dns: invalid mini-IP address ${address}`);
  }
  if (!Number.isInteger(ttlTicks) || ttlTicks < 1) {
    throw new Error(`dns: ttlTicks must be a positive integer, got ${ttlTicks}`);
  }
  const entries = new Map(); // name -> { name, target, expiresAtTick }
  let lookups = 0;
  let cachedHits = 0;
  let authoritative = 0;

  function evictExpired(currentTick = 0) {
    for (const entry of entries.values()) {
      if (currentTick >= entry.expiresAtTick) {
        entries.delete(entry.name);
      }
    }
  }

  // CHECKS: the TTL branch — an entry inside ttlTicks is answered from the
  // ledger (cachedHits increments, the authority is not consulted); a miss
  // or an expired entry consults the authoritative table instead (named
  // counter-example: the expired entry is not answered from the ledger).
  // An unknown name answers NX — no throw at the DNS layer; the fail-loud
  // rule lives at the cross-subnet network boundary (20.9), and the browser
  // renders the NX card without emitting a GET.
  function lookup(name, currentTick = 0) {
    lookups += 1;
    evictExpired(currentTick);
    const hit = entries.get(name);
    if (hit) {
      cachedHits += 1;
      return { status: 'OK', target: hit.target, source: 'cache' };
    }
    authoritative += 1;
    const target = AUTHORITATIVE.get(name);
    if (!target) {
      return { status: 'NX' };
    }
    entries.set(name, { name, target, expiresAtTick: currentTick + ttlTicks });
    return { status: 'OK', target, source: 'authority' };
  }

  function snapshot(currentTick = 0) {
    evictExpired(currentTick);
    return {
      address,
      ttlTicks,
      lookups,
      cachedHits,
      authoritative,
      cache: [...entries.values()].map((entry) => ({
        name: entry.name,
        target: entry.target,
        expiresAtTick: entry.expiresAtTick,
        ttlRemaining: entry.expiresAtTick - currentTick,
      })),
    };
  }

  return {
    get address() {
      return address;
    },
    lookup,
    snapshot,
  };
}

// DOCUMENTS: the Stage 6 component — a cross-subnet Router joining the 10.x
// and 20.x network fabrics. A frame whose destination sits on the other
// side takes exactly one router hop (the routed counter increments) and is
// then delivered by the far fabric's own send/deliverToQueue contract;
// same-subnet frames are the stage 1-5 concern and bypass the router.
//
// CHECKS: both interface addresses are validated as two-number mini-IPs on
// different subnets (a same-subnet router is a mis-wiring, not a feature),
// and a forward into a subnet that no joined fabric owns fails loud.
export function createRouter({ leftAddress = '10.65', rightAddress = '20.1' } = {}) {
  for (const [name, addr] of [
    ['leftAddress', leftAddress],
    ['rightAddress', rightAddress],
  ]) {
    if (!/^\d+\.\d+$/.test(addr)) {
      throw new Error(`router: invalid mini-IP address ${name}=${addr}`);
    }
  }
  const netOf = (addr) => String(addr).split('.')[0];
  if (netOf(leftAddress) === netOf(rightAddress)) {
    throw new Error(
      `router: left and right interfaces must sit on different subnets, got ${leftAddress} and ${rightAddress}`,
    );
  }
  let routed = 0;
  let left = null;
  let right = null;

  // The 20-side interface answers a frame addressed to rightAddress so the
  // one-hop route is demonstrable while subnet 20 is otherwise empty
  // (Stage 6b replaces it with the CDN edge at 20.1).
  const rightInterface = {
    handleRequest: () => `200 Router ${rightAddress}`,
  };

  function farFabric(address) {
    const net = netOf(address);
    if (right && net === netOf(rightAddress)) return right;
    if (left && net === netOf(leftAddress)) return left;
    return null;
  }

  return {
    get leftAddress() {
      return leftAddress;
    },
    get rightAddress() {
      return rightAddress;
    },
    rightInterface,

    // CHECKS: join wires both fabrics in; the engine registers the 20-side
    // interface at rightAddress in the far fabric so 20.1 stays the one
    // reachable target and 20.9 keeps failing loud at the fabric boundary.
    join(leftNetwork, rightNetwork) {
      left = leftNetwork;
      right = rightNetwork;
    },

    // CHECKS: a cross-subnet frame takes exactly one router hop — routed
    // increments once, then the far fabric delivers by its own contract.
    forward({ from, to, request }) {
      const fabric = farFabric(to);
      if (!fabric) {
        throw new Error(`router: no joined fabric for ${to}`);
      }
      routed += 1;
      return fabric.send({ from, to, request });
    },

    forwardToQueue({ id, from, to, request, atTick, isYou = false }) {
      const fabric = farFabric(to);
      if (!fabric) {
        throw new Error(`router: no joined fabric for ${to}`);
      }
      routed += 1;
      fabric.deliverToQueue({ id, from, to, request, atTick, isYou });
    },

    snapshot() {
      return { leftAddress, rightAddress, routed };
    },
  };
}

// DOCUMENTS: the network — the wiring that lets two-number mini-IP
// addressable components exchange messages. Today it carries slim HTTP
// requests to a registered server; later stages attach more components
// without changing the send/enqueue contract. Stage 6 adds cross-subnet
// routing: a fabric owns one subnet number, and a destination on another
// subnet takes exactly one hop through the attached Router into the far
// fabric's own delivery contract.
//
// CHECKS: every address crossing the wire is validated as a two-number
// mini-IP (<net>.<host>), and sends to unregistered hosts fail loud —
// same-subnet (11.1 with no router attached) and far-subnet (20.9 behind
// the attached Router) alike.
const MINI_IP = /^\d+\.\d+$/;

export function createNetwork(subnet = '10') {
  const servers = new Map();
  let router = null;

  function validate(addr) {
    if (!MINI_IP.test(addr)) {
      throw new Error(`network: invalid mini-IP address ${addr}`);
    }
  }

  function resolve(address) {
    validate(address);
    const server = servers.get(address);
    if (!server) {
      throw new Error(`network: no server at ${address}`);
    }
    return server;
  }

  // CHECKS: a destination on a foreign subnet routes through the attached
  // Router (one hop, the Router counts it); with no Router attached the
  // delivery falls through to the local registry and fails loud there —
  // the stage 1-5 send contract is unchanged.
  function offSubnet(to) {
    return String(to).split('.')[0] !== subnet;
  }

  return {
    registerServer(address, server) {
      validate(address);
      servers.set(address, server);
    },

    resolve,

    attachRouter(attached) {
      router = attached;
    },

    send({ from, to, request }) {
      validate(from);
      validate(to);
      if (offSubnet(to) && router) {
        return router.forward({ from, to, request });
      }
      const server = resolve(to);
      const response = server.handleRequest(request);
      return { from, to, request, response };
    },

    // `isYou` rides through untouched: the engine marks the learner's own
    // interactive-browser request, the server stores it on the queue row.
    deliverToQueue({ id, from, to, request, atTick, isYou = false }) {
      validate(from);
      validate(to);
      if (offSubnet(to) && router) {
        router.forwardToQueue({ id, from, to, request, atTick, isYou });
        return;
      }
      const server = resolve(to);
      server.enqueue({ id, from, to, request, atTick, isYou });
    },
  };
}

