// Which card executes the hop, and which wire lane carries it:
// Stage 1 is emit / route / serve / render; Stage 2 inserts the LB's
// round-robin pick; Stage 3 splits the backend serve into the cache
// lookup (Cache 10.20 answers) and the response emission; Stage 4 adds
// the database hop; Stage 5 adds async worker queue processing; Stage 6
// prefixes the two DNS hops for hosted paths and re-uses the Stage 5 map
// unchanged for host-less paths and the +2 shift for hosted ones.
function stage5HopMaps(snapshot) {
  const backendCard =
    snapshot.trace?.targetServer === '10.12' ? 'node-webserver-2' : 'node-webserver';
  const dbLane = snapshot.trace?.dbOp === 'WRITE' ? 'packet-req-db' : 'packet-res-db';
  if (snapshot.trace?.asyncJob) {
    return {
      owners: {
        1: 'node-browser',
        2: 'node-network',
        3: 'node-lb',
        4: 'node-queue',
        5: 'node-webserver',
        6: 'node-network',
        7: 'node-browser',
        8: 'node-worker',
      },
      lanes: {
        1: 'packet-req-left',
        2: 'packet-req-right',
        3: 'packet-req-lb',
        4: 'packet-req-queue',
        5: 'packet-res-cache',
        6: 'packet-res-right',
        7: 'packet-res-left',
        8: 'packet-res-db',
      },
    };
  }
  return {
    owners: {
      1: 'node-browser',
      2: 'node-network',
      3: 'node-lb',
      4: 'node-db',
      5: backendCard,
      6: 'node-network',
      7: 'node-browser',
      8: 'node-worker',
    },
    lanes: {
      1: 'packet-req-left',
      2: 'packet-req-right',
      3: 'packet-req-lb',
      4: dbLane,
      5: 'packet-res-cache',
      6: 'packet-res-right',
      7: 'packet-res-left',
      8: 'packet-res-worker',
    },
  };
}

function activeHopTarget(snapshot) {
  const hop = snapshot.trace?.hop ?? 0;
  if (snapshot.stage === 6) {
    const t = snapshot.trace ?? {};
    if (t.nx) {
      // NX: ask, answer, and the browser rendering the NX card — no GET
      // hop exists, so no backend card carries the highlight.
      const owners = { 1: 'node-browser', 2: 'node-dns', 3: 'node-browser' };
      const lanes = {
        1: 'packet-req-left',
        2: 'packet-res-left',
        3: 'packet-res-left',
      };
      return { cardId: owners[hop] ?? 'node-browser', laneId: lanes[hop] ?? 'packet-req-left' };
    }
    if (t.host) {
      const five = stage5HopMaps(snapshot);
      const owners = { 1: 'node-browser', 2: 'node-dns' };
      const lanes = { 1: 'packet-req-left', 2: 'packet-res-left' };
      for (const [chainHop, owner] of Object.entries(five.owners)) {
        owners[Number(chainHop) + 2] = owner;
      }
      for (const [chainHop, lane] of Object.entries(five.lanes)) {
        lanes[Number(chainHop) + 2] = lane;
      }
      return { cardId: owners[hop] ?? 'node-browser', laneId: lanes[hop] ?? 'packet-req-left' };
    }
    // Host-less: the Stage 5 map applies at unchanged hop numbers.
    const five = stage5HopMaps(snapshot);
    return { cardId: five.owners[hop] ?? 'node-browser', laneId: five.lanes[hop] ?? 'packet-req-left' };
  }
  if (snapshot.stage === 5) {
