  const snapshot = engine.traceHop({
    method: els.method.value,
    path: els.urlInput.value,
    from: activeBrowserAddress,
  });
  const trace = snapshot.trace ?? {};
  // The published total follows the actual trace shape (host-less Stage 6
  // runs read 8, hosted 10, NX 3); earlier stages fall back to the table.
  const totalHops = trace.totalHops ?? totalHopsFor(snapshot.stage);
