  // ascending) floats above the previous run in #journey-log.
  if (trace.hop === 1) traceRunId = nextJourneyRun();
  addToJourney(`hop ${trace.hop}/${totalHops}`, snapshot.lastFrame, {
    run: traceRunId,
    hop: trace.hop,
  });
  updateView(snapshot);
  return snapshot;
}

