    laneId: 'wire-servers-cache',
    stages: [3, 4, 5, 6],
    wireIds: ['wire-webserver-cache', 'wire-webserver-2-cache'],
    capTo: 'node-cache',
    capDx: -175, // 15.5rem card half + chip half + margin, in world px
  },
];

